const N={b1:'BotBhai',b2:'JobCard',b3:'Kits',b4:'Tab Lifeboat',b5:'Deals & Tools',b6:'Ledger Peaks',b7:'Trading Lab'};
const kit=$('All kit items').all().map(i=>i.json).filter(r=>r.stream);
const pipe=$('All pipeline deals').all().map(i=>i.json).filter(r=>r.stream);
const leads=$('All leads').all().map(i=>i.json).filter(r=>r.business);
const today=new Date(Date.now()+330*60000).toISOString().slice(0,10);
let tg='Kalpa HQ revenue report '+today+'\n'; let md='# Kalpa HQ revenue report, '+today+'\n\nMade by the n8n workflow "Kalpa HQ Revenue Rollup" from KL GTM Kit, KL Pipeline and KL Leads. Drafts are written by free models: check every [TO VERIFY] and [CEO] mark before use.\n\n| Business | Kit items done | Need CEO | Leads | Open deals | Pipeline value (INR) | Won (INR) |\n|---|---|---|---|---|---|---|\n';
let totDone=0,totAll=0,totPipe=0,totWon=0; const body=[];
for (const s of Object.keys(N)) {
 const k=kit.filter(r=>r.stream===s); const live=k.filter(r=>r.status!=='skip-sebi'); const done=live.filter(r=>r.status==='draft'||r.status==='approved');
 const ceo=done.filter(r=>r.needs_ceo).length; const p=pipe.filter(r=>r.stream===s);
 const open=p.filter(r=>!['won','lost'].includes(r.stage)); const pv=open.reduce((a,r)=>a+(Number(r.value_inr)||0),0); const won=p.filter(r=>r.stage==='won').reduce((a,r)=>a+(Number(r.value_inr)||0),0);
 const l=leads.filter(r=>r.stream===s || (!r.stream && s==='b1')).length;
 totDone+=done.length; totAll+=live.length; totPipe+=pv; totWon+=won;
 md+='| '+s+' '+N[s]+' | '+done.length+'/'+live.length+' | '+ceo+' | '+l+' | '+open.length+' | '+pv+' | '+won+' |\n';
 tg+='\n'+N[s]+': kit '+done.length+'/'+live.length+', CEO checks '+ceo+', leads '+l+', open deals '+open.length+(won?', won Rs '+won:'');
 if (done.length) { body.push('\n## '+s+' '+N[s]+'\n'); for (const r of done.sort((a,b)=>a.item_no-b.item_no)) body.push('\n### '+r.item_no+'. '+r.item+' (owner: '+r.owner_agent+', '+r.pod+')\n\n'+String(r.output||'')+'\n'); }
}
md+='\n**All businesses:** kit '+totDone+'/'+totAll+' items drafted, open pipeline Rs '+totPipe+', won Rs '+totWon+'.\n'+body.join('');
tg+='\n\nTotal: '+totDone+'/'+totAll+' items drafted, pipeline Rs '+totPipe+', won Rs '+totWon+'. Full report in GitHub 00-hq/revenue/daily/'+today+'.md';
return [{json:{today,tg,md}}];
